def solution(image: list[list[int]]) -> list[list[float]]:
    # BUG: int 변환 때문에 소수 부분이 사라집니다.
    return [[int(pixel / 127.5 - 1.0) for pixel in row] for row in image]

def solution(target_versions: set[str]) -> list[str]:
    if not target_versions:
        return ['py3', 'py2_function_print', 'py2']
    if all(version.startswith('py3') for version in target_versions):
        return ['py3', 'py2_function_print']
    # BUG: 함수형 print를 처리하는 문법 후보가 빠져 있습니다.
    return ['py2']

import re


def solution(path: str, data: str) -> dict | None:
    # BUG: 최신 Kali가 사용하는 /etc/os-release를 확인하지 않습니다.
    if path == '/etc/lsb-release' and 'Kali' in data:
        match = re.search(r'DISTRIB_RELEASE=(.*)', data)
        return {
            'distribution': 'Kali',
            'version': match.group(1).strip() if match else None,
        }
    return None
